css:
.optima-sim-container {
    padding: 20px;
    background: linear-gradient(135deg, #eef2f7 0%, #dfe6ed 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

.optima-sim-header {
    background: linear-gradient(135deg, #4a63c8 0%, #6c3fa0 100%);
    color: white;
    padding: 30px;
    border-radius: 20px;
    margin-bottom: 24px;
    box-shadow: 0 8px 20px rgba(74,99,200,0.3);
    text-align: center;
}

.optima-sim-header h1 {
    margin: 0 0 6px 0;
    font-size: 1.8rem;
}

.optima-sim-header p {
    margin: 0;
    opacity: 0.85;
    font-size: 1rem;
}

.optima-sim-period-counter {
    text-align: center;
    font-size: 1.1rem;
    margin-bottom: 20px;
    color: #555;
}

.optima-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 16px;
    margin-bottom: 24px;
}

.optima-sim-status-card {
    background: white;
    border-radius: 14px;
    padding: 20px 16px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    text-align: center;
    transition: transform 0.3s ease;
}

.optima-sim-status-card:hover {
    transform: translateY(-4px);
}

.optima-sim-card-score {
    border-top: 4px solid #4a63c8;
}

.optima-sim-card-avg {
    border-top: 4px solid #27ae60;
}

.optima-sim-card-round {
    border-top: 4px solid #e67e22;
}

.optima-sim-card-obj {
    border-top: 4px solid #8e44ad;
}

.optima-sim-label {
    color: #777;
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 6px;
}

.optima-sim-value {
    font-size: 1.8rem;
    font-weight: 700;
    color: #333;
}

.optima-sim-briefing {
    background: white;
    border-radius: 14px;
    padding: 24px;
    margin-bottom: 24px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    border-left: 5px solid #4a63c8;
}

.optima-sim-briefing h3 {
    color: #4a63c8;
    margin-top: 0;
    margin-bottom: 12px;
    font-size: 1.25rem;
}

.optima-sim-briefing-text {
    color: #444;
    line-height: 1.65;
    margin-bottom: 16px;
}

.optima-sim-constraints {
    background: #f8f9fa;
    border-radius: 10px;
    padding: 14px 18px;
    margin-bottom: 12px;
    font-family: 'Courier New', monospace;
    font-size: 0.92rem;
    line-height: 1.8;
}

.optima-sim-objective {
    background: #eef0ff;
    border-radius: 10px;
    padding: 12px 18px;
    font-weight: 600;
    color: #4a63c8;
    font-size: 1rem;
}

.optima-sim-controls {
    background: white;
    border-radius: 14px;
    padding: 24px;
    margin-bottom: 24px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
}

.optima-sim-controls h3 {
    margin-top: 0;
    margin-bottom: 16px;
    color: #333;
    font-size: 1.15rem;
}

.optima-sim-input-row {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 16px;
    margin-bottom: 20px;
}

.optima-sim-input-group label {
    display: block;
    font-weight: 600;
    color: #555;
    margin-bottom: 6px;
    font-size: 0.9rem;
}

.optima-sim-input-group input {
    width: 100%;
    padding: 10px 12px;
    border: 2px solid #ddd;
    border-radius: 8px;
    font-size: 1.1rem;
    transition: border-color 0.2s;
}

.optima-sim-input-group input:focus {
    border-color: #4a63c8;
    outline: none;
}

.optima-sim-btn-row {
    display: flex;
    gap: 12px;
    align-items: center;
}

.optima-sim-container .btn-primary {
    background: linear-gradient(135deg, #4a63c8, #6c3fa0);
    border: none;
    padding: 12px 32px;
    font-size: 1.05rem;
    border-radius: 10px;
    font-weight: 600;
}

.optima-sim-container .btn-primary:hover {
    opacity: 0.9;
}

.optima-sim-results {
    background: white;
    border-radius: 14px;
    padding: 24px;
    margin-bottom: 24px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    border-left: 5px solid #27ae60;
}

.optima-sim-results h3 {
    margin-top: 0;
    margin-bottom: 16px;
    color: #27ae60;
}

.optima-sim-results-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
    margin-bottom: 16px;
}

.optima-sim-result-item {
    background: #f8f9fa;
    border-radius: 10px;
    padding: 14px;
    text-align: center;
}

.optima-sim-result-item .optima-sim-label {
    margin-bottom: 4px;
}

.optima-sim-result-item .optima-sim-value {
    font-size: 1.4rem;
}

.optima-sim-shadow-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 12px;
    font-size: 0.9rem;
}

.optima-sim-shadow-table th {
    background: #4a63c8;
    color: white;
    padding: 10px 12px;
    text-align: left;
    font-weight: 600;
}

.optima-sim-shadow-table td {
    padding: 10px 12px;
    border-bottom: 1px solid #eee;
}

.optima-sim-shadow-table tr:nth-child(even) {
    background: #f8f9fa;
}

.optima-sim-binding {
    color: #e74c3c;
    font-weight: 600;
}

.optima-sim-nonbinding {
    color: #27ae60;
}

.optima-sim-insight-box {
    background: linear-gradient(135deg, #fff8e1, #fff3cd);
    border-radius: 10px;
    padding: 14px 18px;
    margin-top: 14px;
    border-left: 4px solid #f39c12;
    font-size: 0.95rem;
    line-height: 1.6;
}

.optima-sim-infeasible {
    background: #fde8e8;
    border-radius: 10px;
    padding: 14px 18px;
    color: #c0392b;
    font-weight: 600;
    margin-bottom: 12px;
}

.optima-sim-history {
    margin-bottom: 24px;
}

.optima-sim-chart {
    background: white;
    border-radius: 14px;
    padding: 20px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    height: 300px;
}

@media (max-width: 768px) {
    .optima-sim-status-cards {
        grid-template-columns: repeat(2, 1fr);
    }
    .optima-sim-input-row {
        grid-template-columns: 1fr;
    }
    .optima-sim-results-grid {
        grid-template-columns: 1fr;
    }
}

