(function() {
    'use strict';

    class OptimaSolverAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'OptimaSolver: LP & Optimization Lab';
            this.version = '1.1.0';

            this.ROUNDS = [
                {
                    title: { en: 'Scenario 1: Production Mix Optimization', es: 'Escenario 1: Optimización de Mezcla de Producción' },
                    briefing: {
                        en: 'FarmTech Industries produces two products (A and B) using shared manufacturing resources. Each unit of A requires 2 machine-hours and 1 kg of raw material. Each unit of B requires 1 machine-hour and 2 kg of raw material. Product A generates €45 profit per unit and Product B generates €30 per unit. Determine the optimal production quantities to maximize total profit.',
                        es: 'FarmTech Industries produce dos productos (A y B) con recursos compartidos. Cada unidad de A requiere 2 horas-máquina y 1 kg de materia prima. Cada unidad de B requiere 1 hora-máquina y 2 kg. El producto A genera €45 de beneficio por unidad y el B genera €30. Determine las cantidades óptimas para maximizar el beneficio.'
                    },
                    activeVars: 2,
                    varLabels: { en: ['Units of Product A', 'Units of Product B', ''], es: ['Unidades Producto A', 'Unidades Producto B', ''] },
                    varMins: [0, 0, 0], varMaxs: [200, 200, 0], varDefaults: [0, 0, 0],
                    constraints: [
                        { coeffs: [2, 1, 0], rhs: 200, type: 'leq', desc: { en: '2A + B ≤ 200  (Machine Hours)', es: '2A + B ≤ 200  (Horas Máquina)' } },
                        { coeffs: [1, 2, 0], rhs: 160, type: 'leq', desc: { en: 'A + 2B ≤ 160  (Raw Materials kg)', es: 'A + 2B ≤ 160  (Materia Prima kg)' } },
                        { coeffs: [1, 0, 0], rhs: 80,  type: 'leq', desc: { en: 'A ≤ 80  (Max Capacity for A)', es: 'A ≤ 80  (Capacidad Máx. de A)' } }
                    ],
                    objCoeffs: [45, 30, 0], objType: 'max',
                    objDesc: { en: 'Maximize Z = 45A + 30B  (€ Profit)', es: 'Maximizar Z = 45A + 30B  (€ Beneficio)' },
                    optimalValue: 4800, optimalSolution: [80, 40, 0],
                    optimalDesc: { en: 'A = 80, B = 40  →  Z = €4,800', es: 'A = 80, B = 40  →  Z = €4.800' },
                    shadowPrices: [
                        { name: { en: 'Machine Hours', es: 'Horas Máquina' }, value: 20, binding: true, explanation: { en: 'Each additional machine-hour adds €20 to maximum profit', es: 'Cada hora-máquina adicional aporta €20 al beneficio máximo' } },
                        { name: { en: 'Raw Materials', es: 'Materia Prima' }, value: 5, binding: true, explanation: { en: 'Each additional kg of raw material adds €5 to profit', es: 'Cada kg adicional de materia prima aporta €5 al beneficio' } },
                        { name: { en: 'Capacity A', es: 'Capacidad A' }, value: 0, binding: true, explanation: { en: 'Redundant at optimum — relaxing this does not improve profit', es: 'Redundante en el óptimo — relajarla no mejora el beneficio' } }
                    ],
                    insight: { en: 'Machine time is the most valuable resource (€20/hr). If overtime costs less than €20/hr, it is profitable to schedule extra hours.', es: 'El tiempo de máquina es el recurso más valioso (€20/hr). Si las horas extra cuestan menos de €20/hr, es rentable programarlas.' }
                },
                {
                    title: { en: 'Scenario 2: Workforce Scheduling', es: 'Escenario 2: Programación de Personal' },
                    briefing: {
                        en: 'MediCare Hospital must staff three shifts: Morning, Afternoon, and Night. Morning and Afternoon workers cost $60/shift each; Night workers cost $80/shift. Minimum coverage requirements: Morning ≥ 8, Afternoon ≥ 6, Night ≥ 3. The daily staffing budget is $1,500. Maximize total worker coverage (sum of all workers deployed).',
                        es: 'El Hospital MediCare debe cubrir tres turnos: Mañana, Tarde y Noche. Los trabajadores de Mañana y Tarde cuestan $60/turno; los de Noche $80/turno. Cobertura mínima: Mañana ≥ 8, Tarde ≥ 6, Noche ≥ 3. Presupuesto diario: $1.500. Maximice la cobertura total.'
                    },
                    activeVars: 3,
                    varLabels: { en: ['Morning Workers', 'Afternoon Workers', 'Night Workers'], es: ['Turno Mañana', 'Turno Tarde', 'Turno Noche'] },
                    varMins: [0, 0, 0], varMaxs: [30, 30, 30], varDefaults: [8, 6, 3],
                    constraints: [
                        { coeffs: [60, 60, 80], rhs: 1500, type: 'leq', desc: { en: '60M + 60A + 80N ≤ 1500  (Budget $)', es: '60M + 60A + 80N ≤ 1500  (Presupuesto $)' } },
                        { coeffs: [1, 0, 0], rhs: 8, type: 'geq', desc: { en: 'M ≥ 8  (Min Morning)', es: 'M ≥ 8  (Mín Mañana)' } },
                        { coeffs: [0, 1, 0], rhs: 6, type: 'geq', desc: { en: 'A ≥ 6  (Min Afternoon)', es: 'A ≥ 6  (Mín Tarde)' } },
                        { coeffs: [0, 0, 1], rhs: 3, type: 'geq', desc: { en: 'N ≥ 3  (Min Night)', es: 'N ≥ 3  (Mín Noche)' } }
                    ],
                    objCoeffs: [1, 1, 1], objType: 'max',
                    objDesc: { en: 'Maximize Z = M + A + N  (Total Coverage)', es: 'Maximizar Z = M + A + N  (Cobertura Total)' },
                    optimalValue: 24, optimalSolution: [15, 6, 3],
                    optimalDesc: { en: 'M = 15, A = 6, N = 3  →  Z = 24 workers', es: 'M = 15, A = 6, N = 3  →  Z = 24 trabajadores' },
                    shadowPrices: [
                        { name: { en: 'Budget', es: 'Presupuesto' }, value: 0.017, binding: true, explanation: { en: 'Each additional $1 of budget adds ~0.017 workers (1 worker per $60)', es: 'Cada $1 adicional añade ~0,017 trabajadores (1 trabajador por $60)' } },
                        { name: { en: 'Min Morning', es: 'Mín Mañana' }, value: 0, binding: false, explanation: { en: 'Not binding — morning staffing exceeds minimum by 7', es: 'No vinculante — la dotación matutina supera el mínimo en 7' } },
                        { name: { en: 'Min Afternoon', es: 'Mín Tarde' }, value: 0, binding: true, explanation: { en: 'Binding but shadow price is zero: swapping with morning has equal cost', es: 'Vinculante pero precio sombra cero: intercambiar con mañana tiene igual coste' } },
                        { name: { en: 'Min Night', es: 'Mín Noche' }, value: 0.33, binding: true, explanation: { en: 'Relaxing night minimum by 1 saves $20 (80−60), gaining 0.33 extra workers', es: 'Relajar el mínimo nocturno en 1 ahorra $20 (80−60), ganando 0,33 trabajadores' } }
                    ],
                    insight: { en: 'Night workers cost 33% more than day workers. Minimizing night coverage and maximizing cheaper day shifts is the key to optimal staffing within budget.', es: 'Los trabajadores nocturnos cuestan un 33% más. Minimizar la cobertura nocturna y maximizar los turnos diurnos más baratos es clave para la dotación óptima.' }
                },
                {
                    title: { en: 'Scenario 3: Distribution Network', es: 'Escenario 3: Red de Distribución' },
                    briefing: {
                        en: 'LogiMax has one factory that ships to two cities. Shipping to City A yields €35/unit profit; shipping to City B yields €28/unit. Factory production capacity is 500 units. City A can absorb at most 300 units; City B at most 250. Contractual obligations require at least 100 units to A and 80 to B. Maximize total distribution profit.',
                        es: 'LogiMax tiene una fábrica que envía a dos ciudades. Enviar a Ciudad A da €35/unidad de beneficio; a Ciudad B, €28/unidad. Capacidad: 500 unidades. Ciudad A absorbe máximo 300; Ciudad B máximo 250. Contratos obligan a enviar mínimo 100 a A y 80 a B. Maximice el beneficio de distribución.'
                    },
                    activeVars: 2,
                    varLabels: { en: ['Units to City A', 'Units to City B', ''], es: ['Unidades a Ciudad A', 'Unidades a Ciudad B', ''] },
                    varMins: [0, 0, 0], varMaxs: [500, 500, 0], varDefaults: [100, 80, 0],
                    constraints: [
                        { coeffs: [1, 1, 0], rhs: 500, type: 'leq', desc: { en: 'A + B ≤ 500  (Production Capacity)', es: 'A + B ≤ 500  (Capacidad Producción)' } },
                        { coeffs: [1, 0, 0], rhs: 300, type: 'leq', desc: { en: 'A ≤ 300  (City A Max Demand)', es: 'A ≤ 300  (Demanda Máx Ciudad A)' } },
                        { coeffs: [0, 1, 0], rhs: 250, type: 'leq', desc: { en: 'B ≤ 250  (City B Max Demand)', es: 'B ≤ 250  (Demanda Máx Ciudad B)' } },
                        { coeffs: [1, 0, 0], rhs: 100, type: 'geq', desc: { en: 'A ≥ 100  (Contract Minimum A)', es: 'A ≥ 100  (Contrato Mín A)' } },
                        { coeffs: [0, 1, 0], rhs: 80,  type: 'geq', desc: { en: 'B ≥ 80   (Contract Minimum B)', es: 'B ≥ 80   (Contrato Mín B)' } }
                    ],
                    objCoeffs: [35, 28, 0], objType: 'max',
                    objDesc: { en: 'Maximize Z = 35A + 28B  (€ Distribution Profit)', es: 'Maximizar Z = 35A + 28B  (€ Beneficio Distribución)' },
                    optimalValue: 16100, optimalSolution: [300, 200, 0],
                    optimalDesc: { en: 'A = 300, B = 200  →  Z = €16,100', es: 'A = 300, B = 200  →  Z = €16.100' },
                    shadowPrices: [
                        { name: { en: 'Production Capacity', es: 'Capacidad Producción' }, value: 28, binding: true, explanation: { en: 'Each extra unit of capacity adds €28 (goes to City B, the uncapped route)', es: 'Cada unidad extra de capacidad aporta €28 (va a Ciudad B, ruta sin tope)' } },
                        { name: { en: 'City A Max Demand', es: 'Demanda Máx A' }, value: 7, binding: true, explanation: { en: 'Raising A demand cap by 1 shifts a unit from B (€28) to A (€35), net +€7', es: 'Subir el tope de A en 1 cambia una unidad de B (€28) a A (€35), neto +€7' } },
                        { name: { en: 'City B Max Demand', es: 'Demanda Máx B' }, value: 0, binding: false, explanation: { en: 'Not binding — B receives 200 of a possible 250', es: 'No vinculante — B recibe 200 de un máximo de 250' } },
                        { name: { en: 'Contract Min A', es: 'Contrato Mín A' }, value: 0, binding: false, explanation: { en: 'Not binding — optimal ships 300, far above the 100 minimum', es: 'No vinculante — el óptimo envía 300, muy por encima del mínimo 100' } },
                        { name: { en: 'Contract Min B', es: 'Contrato Mín B' }, value: 0, binding: false, explanation: { en: 'Not binding — optimal ships 200, above the 80 minimum', es: 'No vinculante — el óptimo envía 200, por encima del mínimo 80' } }
                    ],
                    insight: { en: 'The shadow price of capacity (€28) equals the marginal profit of the least profitable active route. Investing in capacity is profitable only if the cost per unit is below €28.', es: 'El precio sombra de capacidad (€28) iguala el beneficio marginal de la ruta activa menos rentable. Invertir en capacidad es rentable solo si el coste unitario es inferior a €28.' }
                },
                {
                    title: { en: 'Scenario 4: Investment Portfolio', es: 'Escenario 4: Cartera de Inversión' },
                    briefing: {
                        en: 'WealthBridge must allocate a portfolio across three asset classes: Bonds (4% expected return), Stocks (10% return), and Real Estate (7% return). Regulatory rules require: Bonds ≥ 20% of portfolio, Stocks ≤ 50%, Real Estate ≤ 40%. The full budget must be allocated (total = 100%). Maximize expected portfolio return.',
                        es: 'WealthBridge debe asignar una cartera entre tres clases de activos: Bonos (4% retorno), Acciones (10%) e Inmuebles (7%). La regulación exige: Bonos ≥ 20%, Acciones ≤ 50%, Inmuebles ≤ 40%. Todo el presupuesto debe asignarse (total = 100%). Maximice el retorno esperado.'
                    },
                    activeVars: 3,
                    varLabels: { en: ['Bonds (%)', 'Stocks (%)', 'Real Estate (%)'], es: ['Bonos (%)', 'Acciones (%)', 'Inmuebles (%)'] },
                    varMins: [0, 0, 0], varMaxs: [100, 100, 100], varDefaults: [34, 33, 33],
                    constraints: [
                        { coeffs: [1, 1, 1], rhs: 100, type: 'eq',  desc: { en: 'B + S + R = 100  (Full Allocation)', es: 'B + S + R = 100  (Asignación Total)' } },
                        { coeffs: [1, 0, 0], rhs: 20,  type: 'geq', desc: { en: 'B ≥ 20  (Min Bonds %)', es: 'B ≥ 20  (Mín Bonos %)' } },
                        { coeffs: [0, 1, 0], rhs: 50,  type: 'leq', desc: { en: 'S ≤ 50  (Max Stocks %)', es: 'S ≤ 50  (Máx Acciones %)' } },
                        { coeffs: [0, 0, 1], rhs: 40,  type: 'leq', desc: { en: 'R ≤ 40  (Max Real Estate %)', es: 'R ≤ 40  (Máx Inmuebles %)' } }
                    ],
                    objCoeffs: [4, 10, 7], objType: 'max',
                    objDesc: { en: 'Maximize Z = 4B + 10S + 7R  (Return × 10)', es: 'Maximizar Z = 4B + 10S + 7R  (Retorno × 10)' },
                    optimalValue: 790, optimalSolution: [20, 50, 30],
                    optimalDesc: { en: 'B = 20%, S = 50%, R = 30%  →  Z = 790 (7.9% return)', es: 'B = 20%, S = 50%, R = 30%  →  Z = 790 (7,9% retorno)' },
                    shadowPrices: [
                        { name: { en: 'Full Allocation', es: 'Asignación Total' }, value: 7, binding: true, explanation: { en: 'Each additional 1% of budget adds 7 to objective (goes to Real Estate at 7%)', es: 'Cada 1% adicional de presupuesto aporta 7 al objetivo (va a Inmuebles al 7%)' } },
                        { name: { en: 'Min Bonds', es: 'Mín Bonos' }, value: 3, binding: true, explanation: { en: 'Relaxing min bonds by 1% shifts allocation to Real Estate: +7 − 4 = +3', es: 'Relajar mín bonos en 1% reasigna a Inmuebles: +7 − 4 = +3' } },
                        { name: { en: 'Max Stocks', es: 'Máx Acciones' }, value: 3, binding: true, explanation: { en: 'Raising max stocks by 1% shifts from Real Estate: +10 − 7 = +3', es: 'Subir máx acciones en 1% cambia desde Inmuebles: +10 − 7 = +3' } },
                        { name: { en: 'Max Real Estate', es: 'Máx Inmuebles' }, value: 0, binding: false, explanation: { en: 'Not binding — only 30% allocated vs. 40% cap', es: 'No vinculante — solo 30% asignado vs. tope de 40%' } }
                    ],
                    insight: { en: 'The shadow prices reveal that loosening either the bond floor or stock ceiling by 1% yields the same +3 improvement. A portfolio manager should lobby for whichever regulatory change is more feasible.', es: 'Los precios sombra revelan que relajar el piso de bonos o el techo de acciones en 1% produce la misma mejora de +3. El gestor debe buscar el cambio regulatorio más viable.' }
                },
                {
                    title: { en: 'Scenario 5: Marketing Mix Optimization', es: 'Escenario 5: Optimización del Mix de Marketing' },
                    briefing: {
                        en: 'ClickBoost has a $100K marketing budget to allocate across Social Media, Search Ads, and Email campaigns. Conversion rates: Social = 40 conversions per $K, Search = 65 per $K, Email = 80 per $K. Constraints: Social $10–$40K (brand presence), Search $15–$50K (channel capacity), Email $5–$30K (list size). Maximize total conversions.',
                        es: 'ClickBoost tiene $100K de presupuesto para Social Media, Anuncios de Búsqueda y Email. Tasas de conversión: Social = 40 por $K, Búsqueda = 65 por $K, Email = 80 por $K. Límites: Social $10–$40K, Búsqueda $15–$50K, Email $5–$30K. Maximice las conversiones totales.'
                    },
                    activeVars: 3,
                    varLabels: { en: ['Social Media ($K)', 'Search Ads ($K)', 'Email ($K)'], es: ['Social Media ($K)', 'Anuncios Búsqueda ($K)', 'Email ($K)'] },
                    varMins: [0, 0, 0], varMaxs: [100, 100, 100], varDefaults: [10, 15, 5],
                    constraints: [
                        { coeffs: [1, 1, 1], rhs: 100, type: 'leq', desc: { en: 'So + Se + Em ≤ 100  (Total Budget $K)', es: 'So + Se + Em ≤ 100  (Presupuesto Total $K)' } },
                        { coeffs: [1, 0, 0], rhs: 10,  type: 'geq', desc: { en: 'So ≥ 10  (Min Social)', es: 'So ≥ 10  (Mín Social)' } },
                        { coeffs: [0, 1, 0], rhs: 15,  type: 'geq', desc: { en: 'Se ≥ 15  (Min Search)', es: 'Se ≥ 15  (Mín Búsqueda)' } },
                        { coeffs: [0, 0, 1], rhs: 5,   type: 'geq', desc: { en: 'Em ≥ 5   (Min Email)', es: 'Em ≥ 5   (Mín Email)' } },
                        { coeffs: [1, 0, 0], rhs: 40,  type: 'leq', desc: { en: 'So ≤ 40  (Max Social)', es: 'So ≤ 40  (Máx Social)' } },
                        { coeffs: [0, 1, 0], rhs: 50,  type: 'leq', desc: { en: 'Se ≤ 50  (Max Search)', es: 'Se ≤ 50  (Máx Búsqueda)' } },
                        { coeffs: [0, 0, 1], rhs: 30,  type: 'leq', desc: { en: 'Em ≤ 30  (Max Email)', es: 'Em ≤ 30  (Máx Email)' } }
                    ],
                    objCoeffs: [40, 65, 80], objType: 'max',
                    objDesc: { en: 'Maximize Z = 40So + 65Se + 80Em  (Conversions)', es: 'Maximizar Z = 40So + 65Se + 80Em  (Conversiones)' },
                    optimalValue: 6450, optimalSolution: [20, 50, 30],
