        _lang() {
            // Read the framework's CANONICAL language property first (.language), then the
            // legacy .currentLanguage, then <html lang>, then default 'en'. Per
            // Lessons_Learned_USF_i18n_and_Modals.md, relying on .currentLanguage alone
            // silently falls back to English on platforms that only set .language. (v1.1 fix)
            var sim = window.mySimulation;
            var raw = (sim && sim.language) || (sim && sim.currentLanguage) || document.documentElement.lang || 'en';
            return (raw && raw.toString().toLowerCase().indexOf('es') === 0) ? 'es' : 'en';
        }

        _t(obj) {
            var l = this._lang();
            return (obj && obj[l]) ? obj[l] : (obj ? obj['en'] || '' : '');
        }

        initialize(state) {
            // Reset domainState on a fresh start OR whenever there is no completed-round
            // history (e.g. the framework calls initialize() after "Undo" pops the last
            // row and history becomes empty). The old guard only checked for an *empty*
            // domainState, so an undo-to-start left the already-counted state in place and
            // the next submit double-counted every accumulator. (v1.1 fix)
            if (!state.domainState || Object.keys(state.domainState).length === 0 || !state.history || state.history.length === 0) {
                state.domainState = {
                    totalScore: 0,
                    scenariosCompleted: 0,
                    scoreHistory: [],
                    efficiencyHistory: [],
                    objectiveHistory: [],
                    optimalHistory: [],
                    lastResultsHTML: ''
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    var1: 0,
                    var2: 0,
                    var3: 0
                };
            }
            this._updateBriefing(state);
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var lang = this._lang();

            var titleEl = document.getElementById('roundTitle');
            if (titleEl) titleEl.innerHTML = this._t(round.title);

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = this._t(round.briefing);

            var conEl = document.getElementById('constraintList');
            if (conEl) {
                var html = '<strong>' + (lang === 'es' ? 'Restricciones:' : 'Constraints:') + '</strong><br>';
                for (var c = 0; c < round.constraints.length; c++) {
                    html += this._t(round.constraints[c].desc) + '<br>';
                }
                conEl.innerHTML = html;
            }

            var objEl = document.getElementById('objectiveDisplay');
            if (objEl) objEl.innerHTML = this._t(round.objDesc);

            for (var v = 0; v < 3; v++) {
                var grp = document.getElementById('var' + (v + 1) + 'Group');
                var lbl = document.getElementById('var' + (v + 1) + 'Label');
                var inp = document.getElementById('var' + (v + 1) + 'Input');
                if (grp) {
                    if (v < round.activeVars) {
                        grp.style.display = 'block';
                        if (lbl) lbl.textContent = this._t(round.varLabels)[v] || '';
                        if (inp) {
                            inp.min = round.varMins[v];
                            inp.max = round.varMaxs[v];
                            inp.value = round.varDefaults[v];
                        }
                    } else {
                        grp.style.display = 'none';
                        if (inp) inp.value = 0;
                    }
                }
            }

            var rp = document.getElementById('resultsPanel');
            if (rp) rp.style.display = 'none';
        }

        validateDecisions(decisions) {
            // NOTE: must NOT call _updateBriefing() here. It resets every input to its
            // scenario default, so calling it before reading the inputs wiped the student's
            // entries and graded every scenario on the defaults instead. Read-only. (v1.1 fix)
            var inp1 = document.getElementById('var1Input');
            var inp2 = document.getElementById('var2Input');
            var inp3 = document.getElementById('var3Input');
            if (inp1) decisions.var1 = parseFloat(inp1.value) || 0;
            if (inp2) decisions.var2 = parseFloat(inp2.value) || 0;
            if (inp3) decisions.var3 = parseFloat(inp3.value) || 0;

            if (decisions.var1 < 0 || decisions.var2 < 0 || decisions.var3 < 0) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('negative_warning'), 'warning'
                );
                return false;
            }

            return true;
        }

        _checkConstraints(round, vals) {
            var results = [];
            for (var c = 0; c < round.constraints.length; c++) {
                var con = round.constraints[c];
                var lhs = 0;
                for (var j = 0; j < con.coeffs.length; j++) {
                    lhs += con.coeffs[j] * (vals[j] || 0);
                }
                var feasible = true;
                var slack = 0;
                if (con.type === 'leq') {
                    feasible = lhs <= con.rhs + 0.001;
                    slack = con.rhs - lhs;
                } else if (con.type === 'geq') {
                    feasible = lhs >= con.rhs - 0.001;
                    slack = lhs - con.rhs;
                } else {
                    feasible = Math.abs(lhs - con.rhs) < 0.5;
                    slack = 0;
                }
                results.push({ desc: this._t(con.desc), feasible: feasible, lhs: lhs, rhs: con.rhs, type: con.type, slack: slack });
            }
            return results;
        }

        _calcObjective(round, vals) {
            var z = 0;
            for (var j = 0; j < round.objCoeffs.length; j++) {
                z += round.objCoeffs[j] * (vals[j] || 0);
            }
            return z;
        }

        calculateResults(state) {
            var period = state.currentPeriod || 1;
            var idx = Math.min(period - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var vals = [state.decisions.var1, state.decisions.var2, state.decisions.var3];
            var lang = this._lang();

            var conResults = this._checkConstraints(round, vals);
            var allFeasible = conResults.every(function(c) { return c.feasible; });
            var studentObj = this._calcObjective(round, vals);
            var efficiency = 0;
            var score = 0;

            if (allFeasible && round.optimalValue > 0) {
                efficiency = Math.min(100, Math.round((studentObj / round.optimalValue) * 100));
                score = efficiency;
            }

            state.domainState.totalScore += score;
            state.domainState.scenariosCompleted += 1;
            state.domainState.scoreHistory.push(score);
            state.domainState.efficiencyHistory.push(efficiency);
            state.domainState.objectiveHistory.push(studentObj);
            state.domainState.optimalHistory.push(round.optimalValue);

            var self = this;
            var maxP = (window.mySimulation && window.mySimulation.state && window.mySimulation.state.maxPeriods) || this.ROUNDS.length;
            setTimeout(function() {
                // Advance the briefing/inputs to the NEXT scenario first (this also hides the
                // results panel), THEN render the just-completed scenario's analysis so it
                // stays visible. Two fixes vs. the original: (1) results are no longer hidden
                // immediately after being shown; (2) use the captured period (the engine
                // increments state.currentPeriod synchronously right after calculateResults
                // returns, so reading it here rendered two scenarios ahead).
                if (period < maxP) {
                    self._updateBriefing({ currentPeriod: period + 1 });
                }
                self._showResults(round, conResults, allFeasible, studentObj, efficiency, lang);
            }, 400);

            return {
                period: period,
                scenario: self._t(round.title),
                feasible: allFeasible,
                studentObjective: studentObj,
                optimalObjective: round.optimalValue,
                efficiency: efficiency,
                score: score,
                totalScore: state.domainState.totalScore
            };
        }

        _showResults(round, conResults, allFeasible, studentObj, efficiency, lang) {
            var rp = document.getElementById('resultsPanel');
            var rc = document.getElementById('resultsContent');
            if (!rp || !rc) return;

            var html = '';

            if (!allFeasible) {
                html += '<div class="optima-sim-infeasible">';
                html += (lang === 'es' ? '⚠ Solución NO factible — una o más restricciones violadas' : '⚠ Solution is INFEASIBLE — one or more constraints violated');
                html += '</div>';
            }

            html += '<div class="optima-sim-results-grid">';
            html += '<div class="optima-sim-result-item"><div class="optima-sim-label">' + (lang === 'es' ? 'Tu Objetivo' : 'Your Objective') + '</div><div class="optima-sim-value">' + studentObj.toLocaleString() + '</div></div>';
            html += '<div class="optima-sim-result-item"><div class="optima-sim-label">' + (lang === 'es' ? 'Óptimo' : 'Optimal') + '</div><div class="optima-sim-value">' + round.optimalValue.toLocaleString() + '</div></div>';
            html += '<div class="optima-sim-result-item"><div class="optima-sim-label">' + (lang === 'es' ? 'Eficiencia' : 'Efficiency') + '</div><div class="optima-sim-value">' + efficiency + '%</div></div>';
            html += '<div class="optima-sim-result-item"><div class="optima-sim-label">' + (lang === 'es' ? 'Solución Óptima' : 'Optimal Solution') + '</div><div class="optima-sim-value" style="font-size:1rem;">' + this._t(round.optimalDesc) + '</div></div>';
            html += '</div>';

            html += '<h4 style="margin-top:18px;color:#4a63c8;">' + (lang === 'es' ? 'Análisis de Restricciones' : 'Constraint Analysis') + '</h4>';
            html += '<table class="optima-sim-shadow-table"><thead><tr>';
            html += '<th>' + (lang === 'es' ? 'Restricción' : 'Constraint') + '</th>';
            html += '<th>' + (lang === 'es' ? 'Estado' : 'Status') + '</th>';
            html += '<th>' + (lang === 'es' ? 'Holgura' : 'Slack') + '</th>';
            html += '</tr></thead><tbody>';
            for (var c = 0; c < conResults.length; c++) {
                var cr = conResults[c];
                var statusClass = cr.feasible ? (Math.abs(cr.slack) < 0.5 ? 'optima-sim-binding' : 'optima-sim-nonbinding') : 'optima-sim-binding';
                var statusText = '';
                if (!cr.feasible) {
                    statusText = lang === 'es' ? '✖ Violada' : '✖ Violated';
                } else if (Math.abs(cr.slack) < 0.5) {
                    statusText = lang === 'es' ? '● Vinculante' : '● Binding';
                } else {
                    statusText = lang === 'es' ? '○ No vinculante' : '○ Non-binding';
                    statusClass = 'optima-sim-nonbinding';
                }
                html += '<tr><td>' + cr.desc + '</td><td class="' + statusClass + '">' + statusText + '</td><td>' + Math.round(cr.slack * 100) / 100 + '</td></tr>';
            }
            html += '</tbody></table>';

            html += '<h4 style="margin-top:18px;color:#8e44ad;">' + (lang === 'es' ? 'Precios Sombra (Valores Duales)' : 'Shadow Prices (Dual Values)') + '</h4>';
            html += '<table class="optima-sim-shadow-table"><thead><tr>';
            html += '<th>' + (lang === 'es' ? 'Restricción' : 'Constraint') + '</th>';
            html += '<th>' + (lang === 'es' ? 'Precio Sombra' : 'Shadow Price') + '</th>';
            html += '<th>' + (lang === 'es' ? 'Interpretación' : 'Interpretation') + '</th>';
            html += '</tr></thead><tbody>';
            for (var s = 0; s < round.shadowPrices.length; s++) {
                var sp = round.shadowPrices[s];
                html += '<tr><td><strong>' + this._t(sp.name) + '</strong></td>';
                html += '<td>' + sp.value + '</td>';
                html += '<td>' + this._t(sp.explanation) + '</td></tr>';
            }
            html += '</tbody></table>';

            html += '<div class="optima-sim-insight-box"><strong>' + (lang === 'es' ? '💡 Insight Clave:' : '💡 Key Insight:') + '</strong> ' + this._t(round.insight) + '</div>';

            rc.innerHTML = html;
            rp.style.display = 'block';
        }

